INSERT INTO skill_topics(id,skill_id,topic_id,relevance)
SELECT md5('if-st:'||m.s||':'||m.t)::uuid,s.id,t.id,m.relevance
FROM (VALUES
('ai-machine-learning','ai-machine-learning',5),('generative-ai-applications','generative-ai-llm-applications',5),
('data-engineering','data-engineering-warehousing',5),('cloud-platform-engineering','cloud-native-platform-engineering',5),
('cybersecurity','cybersecurity-application-security',5),('quality-engineering','software-testing-quality-engineering',5),
('generative-ai-applications','ai-machine-learning',3),('cloud-platform-engineering','cybersecurity-application-security',3)
) m(s,t,relevance) JOIN skills s ON s.slug=m.s JOIN topics t ON t.slug=m.t
ON CONFLICT DO NOTHING;

