INSERT INTO company_roles(id,company_id,name,slug,description,active,created_at,updated_at)
SELECT md5('if-role:'||c.slug||':'||r.slug)::uuid,c.id,r.name,r.slug,
'Original practice track for this role family. Check the employer job post for current requirements.',TRUE,now(),now()
FROM companies c CROSS JOIN (VALUES
('AI Engineer','ai-engineer'),('Cloud Engineer','cloud-engineer'),('Cybersecurity Analyst','cybersecurity-analyst'),
('Data Analyst','data-analyst'),('Data Engineer','data-engineer'),('Data Scientist','data-scientist'),
('DevOps Engineer','devops-engineer'),('Frontend Engineer','frontend-engineer'),('Generative AI Engineer','generative-ai-engineer'),
('Machine Learning Engineer','machine-learning-engineer'),('MLOps Engineer','mlops-engineer'),('Platform Engineer','platform-engineer'),('QA Engineer','qa-engineer'),('Security Engineer','security-engineer'),('Site Reliability Engineer','site-reliability-engineer'),('Software Engineer','software-engineer')
) r(name,slug) WHERE c.slug IN ('amazon','google','infosys','microsoft','tcs','accenture','ibm','deloitte')
ON CONFLICT DO NOTHING;

