('ai-engineer','ai-machine-learning',5),('ai-engineer','generative-ai-applications',4),('ai-engineer','problem-solving-algorithms',4),('ai-engineer','system-design',3),
('generative-ai-engineer','generative-ai-applications',5),('generative-ai-engineer','ai-machine-learning',4),('generative-ai-engineer','system-design',3),
('mlops-engineer','ai-machine-learning',4),('mlops-engineer','cloud-platform-engineering',5),('mlops-engineer','data-engineering',4),('mlops-engineer','system-design',3),
('platform-engineer','cloud-platform-engineering',5),('platform-engineer','networking-fundamentals',4),('platform-engineer','concurrency-operating-systems',4),('platform-engineer','system-design',4),
('security-engineer','cybersecurity',5),('security-engineer','networking-fundamentals',4),('security-engineer','object-oriented-design',3),('security-engineer','system-design',3),
('site-reliability-engineer','cloud-platform-engineering',5),('site-reliability-engineer','networking-fundamentals',4),('site-reliability-engineer','concurrency-operating-systems',5),('site-reliability-engineer','system-design',4),
('machine-learning-engineer','ai-machine-learning',5),('machine-learning-engineer','problem-solving-algorithms',4),('machine-learning-engineer','database-fundamentals',3),
('data-analyst','database-fundamentals',5),('data-analyst','data-engineering',3),('data-engineer','data-engineering',5),('data-engineer','database-fundamentals',4),
('data-engineer','cloud-platform-engineering',3),('data-scientist','ai-machine-learning',5),('data-scientist','database-fundamentals',4),('data-scientist','problem-solving-algorithms',4),
('cloud-engineer','cloud-platform-engineering',5),('cloud-engineer','networking-fundamentals',4),('cloud-engineer','concurrency-operating-systems',3),
('devops-engineer','cloud-platform-engineering',5),('devops-engineer','networking-fundamentals',4),('devops-engineer','concurrency-operating-systems',4),
('cybersecurity-analyst','cybersecurity',5),('cybersecurity-analyst','networking-fundamentals',4),('cybersecurity-analyst','concurrency-operating-systems',3),
('qa-engineer','quality-engineering',5),('qa-engineer','problem-solving-algorithms',3),('qa-engineer','communication-collaboration',3),
('software-engineer','problem-solving-algorithms',4),('software-engineer','object-oriented-design',4),('software-engineer','database-fundamentals',3),('software-engineer','system-design',3),
('frontend-engineer','problem-solving-algorithms',3),('frontend-engineer','object-oriented-design',4),('frontend-engineer','networking-fundamentals',4)
) m(role_slug,skill_slug,importance) ON m.role_slug=r.slug
JOIN skills s ON s.slug=m.skill_slug
WHERE c.slug IN ('amazon','google','infosys','microsoft','tcs','accenture','ibm','deloitte')
ON CONFLICT DO NOTHING;

WITH q(topic,key,title,prompt,difficulty,opts,answer,explanation,notes,example,misconception) AS (VALUES
('ai-machine-learning','leakage','Detecting target leakage','A feature is recorded only after the event a model predicts. What is the main risk?','MEDIUM',jsonb_build_array('It leaks future information and inflates validation results','It guarantees an unbiased model','It always reduces variance','It prevents dataset splitting'),'The feature leaks future information and inflates validation results','Remove features unavailable at prediction time; otherwise evaluation does not represent production.','Training and evaluation must respect the time and information boundary of prediction.','A credit model cannot use a repayment outcome recorded months after loan approval.','Assuming a strong validation score proves generalization'),
('ai-machine-learning','recall','Selecting a classification metric','A fraud team wants to catch as many fraudulent transactions as possible and can review false alarms. Which metric should it emphasize?','MEDIUM',jsonb_build_array('Recall','Specificity only','Mean squared error','R-squared'),'Recall','Recall measures the share of positive cases found; a human review queue can handle some false alarms.','Choose metrics and thresholds from the relative costs of false positives and false negatives.','A fraud team increases recall and allocates reviewers to inspect additional alerts.','Optimizing accuracy despite class imbalance'),
('generative-ai-llm-applications','grounding','Grounding an LLM answer','A support assistant must answer from internal policy documents. Which design best reduces unsupported claims?','MEDIUM',jsonb_build_array('Retrieve relevant approved passages and require citations or abstention','Increase randomness','Delete source documents after indexing','Ask the model to sound confident'),'Retrieve relevant approved passages and require citations or abstention','Retrieval provides evidence; citations and abstention help when evidence is missing, though they do not eliminate errors.','Evaluate retrieval quality and answer faithfulness separately.','The assistant shows the policy section and says it cannot answer without supporting evidence.','Assuming fluent output is necessarily grounded'),
('generative-ai-llm-applications','injection','Handling prompt injection','A retrieved document tells an assistant to reveal secrets. What should a secure system do?','HARD',jsonb_build_array('Treat retrieved text as untrusted and enforce access permissions in application code','Follow it because retrieved documents are trusted','Put credentials in the system prompt','Disable authorization if the model refuses'),'Treat retrieved text as untrusted and enforce access permissions in application code','Prompt injection can arrive through retrieved content. Application code must enforce access control and tool permissions.','Apply least privilege to retrieval and tools; never place secrets in prompts.','Filter documents by the signed-in user before retrieval and restrict available tools.','Trusting content because it came from retrieval'),
('data-engineering-warehousing','idempotency','Making retries safe','A batch may retry after a timeout even if some writes committed. How can it avoid duplicate records?','MEDIUM',jsonb_build_array('Use stable event keys and idempotent upserts','Generate new random keys on retry','Disable retries forever','Append and ask every consumer to deduplicate'),'Use stable event keys and idempotent upserts','Stable identity lets repeated delivery converge on one logical record; delivery is often at least once.','Design retry semantics and destination writes together.','A retried payment webhook upserts by provider event ID instead of counting twice.','Equating client retries with exactly-once delivery'),
('data-engineering-warehousing','grain','Modeling warehouse facts','Analysts need daily order totals by product and region. What is a useful starting model?','EASY',jsonb_build_array('A fact table with declared order-line grain and product, region, and date dimensions','One text field for every order','A separate duplicated table for each dashboard','Totals without a defined grain'),'A fact table with declared order-line grain and product, region, and date dimensions','A declared grain prevents double counting, while dimensions support consistent analytical slicing.','Document the row meaning, keys, and measure definitions before building dashboards.','Order-line facts can be aggregated consistently by date, product, and region.','Building metrics before defining row meaning'),
('cloud-native-platform-engineering','readiness','Choosing health probes','A service process is alive but cannot reach a required database. Which probe should normally stop it receiving traffic?','MEDIUM',jsonb_build_array('Readiness probe','Liveness probe that restarts it for every database outage','Build-info endpoint','Cached metrics scrape'),'Readiness probe','Readiness controls traffic routing. Liveness should generally detect a stuck process rather than restart-loop on external dependency outages.','Separate process liveness from ability to serve requests to avoid cascading failures.','Instances leave the load balancer during a database outage without endlessly restarting.','Using liveness for every dependency check'),
('cloud-native-platform-engineering','least-privilege','Restricting service identity','A worker only reads one object-storage bucket. Which policy is best?','EASY',jsonb_build_array('Dedicated identity with read access only to the required bucket and path','Shared administrator key in source code','Developer personal account','Wildcard access to every bucket'),'Dedicated identity with read access only to the required bucket and path','Least privilege limits the impact of credential exposure or component compromise.','Use managed or short-lived credentials and review permissions.','A report worker reads exports but cannot delete objects or access customer uploads.','Choosing broad permissions to reduce setup work'),
('cybersecurity-application-security','passwords','Storing passwords','How should an application store account passwords?','EASY',jsonb_build_array('Password-specific adaptive hash with a unique salt','Reversible encryption with a shared key','Fast unsalted hash','Plaintext in an internal table'),'Password-specific adaptive hash with a unique salt','Adaptive password hashing raises offline guessing cost and unique salts prevent shared precomputed work.','Use an established password hashing library and tune its work factor.','A leaked credential table does not expose directly reusable plaintext passwords.','Treating a fast general-purpose hash as password storage'),
('cybersecurity-application-security','object-auth','Preventing object access flaws','A user changes an invoice ID in a URL and sees another customer’s invoice. What control addresses this?','MEDIUM',jsonb_build_array('Authorize access to that invoice for the authenticated user on every request','Use unpredictable IDs as the only control','Hide the URL','Check only that the user is logged in'),'Authorize access to that invoice for the authenticated user on every request','Authentication identifies a user; object-level authorization determines whether they may access the resource.','Test cross-user access on read and write endpoints.','Scope invoice lookup by both invoice ID and authenticated account.','Confusing login with permission'),
('software-testing-quality-engineering','test-level','Selecting test levels','A pricing rule has many edge cases and no network dependencies. Where should most focused coverage live?','EASY',jsonb_build_array('Fast unit tests for the rule plus a few integration boundary tests','Only full browser tests','Manual production checks','No tests because the rule is small'),'Fast unit tests for the rule plus a few integration boundary tests','Pure business logic can be covered quickly at unit level while integration checks verify contracts.','Test behavior at the smallest useful boundary; the test pyramid is a heuristic.','Unit tests cover tax brackets while an integration test verifies API mapping.','Putting all coverage at the slowest level'),
('software-testing-quality-engineering','flaky','Investigating flaky tests','A test fails intermittently in CI but passes locally. What should the team do first?','MEDIUM',jsonb_build_array('Capture context and investigate shared state, timing, ordering, and environment','Add retries until it goes green','Delete it immediately','Increase every timeout without diagnosis'),'Capture context and investigate shared state, timing, ordering, and environment','Flakiness signals nondeterminism. Reproduction data and isolation help locate the cause; blind retries hide defects.','Record seeds, environment, logs, and concurrency conditions.','Inject a deterministic clock when a test currently depends on system time.','Treating intermittent failures as harmless noise')
)
INSERT INTO questions(id,topic_id,title,question_text,difficulty,type,options_json,correct_option_index,answer_text,explanation,option_explanations_json,theory_notes,workplace_example,misconception_label,scenario_context,interview_stage,source_type,source_label,published,archived,created_at,updated_at)
SELECT md5('if-question:'||q.topic||':'||q.key)::uuid,t.id,q.title,q.prompt,q.difficulty,'MCQ',q.opts,0,q.answer,q.explanation,
jsonb_build_array('Correct. '||q.explanation,'This option does not address the stated engineering constraint.','This option does not address the stated engineering constraint.','This option does not address the stated engineering constraint.'),
q.notes,q.example,q.misconception,'Choose the safest and most effective engineering response for the scenario.','TECHNICAL_SCREEN','ORIGINAL','InterviewForge original',TRUE,FALSE,now(),now()
FROM q JOIN topics t ON t.slug=q.topic ON CONFLICT DO NOTHING;

WITH q(topic,key,title,prompt,opts,answer,explanation,notes,example,misconception) AS (VALUES
('ai-machine-learning','drift','Monitoring production drift','A deployed demand model receives inputs that differ substantially from its training data. What should the team do?','["Silently keep using the old score","Monitor input and outcome changes, investigate, and validate any retrained model","Retrain on every request","Delete historical evaluation data"]'::jsonb,'Monitor input and outcome changes, investigate, and validate any retrained model','Production populations can change. Monitoring identifies drift; retraining should pass a fresh evaluation before rollout.','Track data quality and delayed outcome measures, then compare candidate models on recent holdout data.','A forecast service alerts on a seasonal shift and validates a new model before switching traffic.','Assuming model evaluation ends at deployment'),
('generative-ai-llm-applications','evaluation','Evaluating a prompt change','A revised prompt looks better in a few handpicked demos. What is the strongest next step?','["Ship based on those demos","Run a representative, versioned evaluation set with task-specific quality and safety criteria","Compare response length only","Ask the model to grade itself"]'::jsonb,'Run a representative, versioned evaluation set with task-specific quality and safety criteria','Repeatable, representative cases expose regressions that handpicked demonstrations can miss.','Measure answer quality, evidence use, refusal behavior, and safety against known cases.','Compare prompt revisions on difficult and adversarial support requests before release.','Using anecdotal demos as the full evaluation'),
('data-engineering-warehousing','late-events','Processing late events','A stream receives valid events several hours after their event time. Which design supports useful time-window results?','["Use event-time windows with a watermark and explicit late-data policy","Drop all events arriving after one second","Replace event timestamps with arrival timestamps","Sort the unbounded stream entirely in memory"]'::jsonb,'Use event-time windows with a watermark and explicit late-data policy','Event time preserves when activity occurred. A watermark bounds expected delay and the policy defines corrections for later arrivals.','Set lateness based on observed delivery delay and downstream correction needs.','A delayed mobile event updates a daily usage aggregate and emits a correction.','Assuming arrival order equals event order'),
('cloud-native-platform-engineering','latency','Diagnosing service latency','A service latency alert fires. Which signals together are most useful to locate its cause?','["Correlated traces, request metrics, and structured logs","Uncorrelated log strings alone","Last month CPU average","Restart immediately before collecting evidence"]'::jsonb,'Correlated traces, request metrics, and structured logs','Metrics show scope, traces locate slow dependencies, and contextual logs explain events around a request.','Propagate trace context and instrument service boundaries.','A checkout trace shows that added latency comes from an inventory dependency.','Treating one telemetry signal as sufficient'),
('cybersecurity-application-security','secret-leak','Responding to a leaked API key','A production API key appears in a public repository. What is the best immediate response?','["Delete the visible commit and assume it is safe","Revoke or rotate it, investigate its use, and move future secrets to managed storage","Wait for confirmed abuse","Share the key in chat for review"]'::jsonb,'Revoke or rotate it, investigate its use, and move future secrets to managed storage','A public secret should be treated as compromised; removing a commit cannot recall copies already made.','Contain first, then investigate scope and prevent recurrence.','Audit API use after rotation and find systems still using the old key.','Assuming deleting public visibility undoes exposure'),
('software-testing-quality-engineering','risk-tests','Prioritizing regression coverage','Release time is limited. Which area deserves the strongest regression focus?','["High-impact flows with recent changes, complex logic, and costly failure modes","Only screens that changed visually","Whichever tests are easiest to automate","Random cases with no expected outcomes"]'::jsonb,'High-impact flows with recent changes, complex logic, and costly failure modes','Risk-based testing weighs impact and likelihood while considering change scope and complexity.','Use incident history and architecture knowledge to prioritize scarce test time.','A payment retry change receives duplicate-charge and idempotency checks.','Equating test count with risk reduction')
)
INSERT INTO questions(id,topic_id,title,question_text,difficulty,type,options_json,correct_option_index,answer_text,explanation,option_explanations_json,theory_notes,workplace_example,misconception_label,scenario_context,interview_stage,source_type,source_label,published,archived,created_at,updated_at)
SELECT md5('if-question:'||q.topic||':'||q.key)::uuid,t.id,q.title,q.prompt,'MEDIUM','MCQ',q.opts,1,q.answer,q.explanation,
jsonb_build_array('This choice does not address the core problem.','Correct. '||q.explanation,'This choice does not address the core problem.','This choice does not address the core problem.'),
q.notes,q.example,q.misconception,'Choose the safest and most effective engineering response for the scenario.','TECHNICAL_SCREEN','ORIGINAL','InterviewForge original',TRUE,FALSE,now(),now()
FROM q JOIN topics t ON t.slug=q.topic ON CONFLICT DO NOTHING;
